import { spawn } from "node:child_process";
import { mkdir, readFile, readdir, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const marker = "// @mouses-temporary-stub";

const stubFiles = {
  "src/pipeline/split.ts": `${marker}
// Generated by scripts/with-stubs.mjs. The pipeline branch replaces this file.
import { STEM_IDS, type SplitMp3, type SplitResult } from "../contract";

export const splitMp3: SplitMp3 = async (file, onProgress) => {
  onProgress({ stage: "Reading audio", fraction: 0.25 });
  await new Promise((resolve) => setTimeout(resolve, 350));
  const context = new AudioContext();
  try {
    let decoded: AudioBuffer;
    try {
      decoded = await context.decodeAudioData(file.slice(0));
    } catch {
      throw new Error("Could not read that MP3.");
    }
    onProgress({ stage: "Preparing stems", fraction: 0.8 });
    await new Promise((resolve) => setTimeout(resolve, 350));
    const stems = {} as SplitResult["stems"];
    for (const id of STEM_IDS) stems[id] = decoded;
    onProgress({ stage: "Done", fraction: 1 });
    return {
      stems,
      durationSec: decoded.duration,
      bpm: 0,
      lyrics: [],
      chords: [],
    };
  } finally {
    await context.close();
  }
};
`,
  "src/player/Player.tsx": `${marker}
// Generated by scripts/with-stubs.mjs. The player branch replaces this file.
import { STEM_IDS, type ChordChange, type StemId, type WordLyric } from "../contract";

export type PlayerProps = {
  title: string;
  stems: Record<StemId, AudioBuffer>;
  durationSec: number;
  bpm: number;
  lyrics: WordLyric[];
  chords: ChordChange[];
  onBack: () => void;
};

export function Player(props: PlayerProps) {
  const bpm = props.bpm > 0 ? " · " + props.bpm + " BPM" : "";
  return (
    <section className="stub-player">
      <button type="button" className="text-button" onClick={props.onBack}>
        Library
      </button>
      <p className="eyebrow">On this phone</p>
      <h1>{props.title}</h1>
      <p className="stub-facts">{props.durationSec.toFixed(1)} seconds{bpm}</p>
      <ul className="stub-stems">
        {STEM_IDS.map((id) => (
          <li key={id}>
            <span>{id}</span>
            <span>{props.stems[id].numberOfChannels} ch</span>
          </li>
        ))}
      </ul>
      <p className="stub-facts">
        {props.lyrics.length} words · {props.chords.length} chords
      </p>
    </section>
  );
}
`,
};

const args = process.argv.slice(2).filter((arg) => arg !== "--keep");
const keep = process.argv.includes("--keep");
const build = args[0] === "--build";
const command = build ? "tsc --noEmit && vite build" : args.join(" ");

if (!command) {
  console.error("Usage: node scripts/with-stubs.mjs [--keep] <command>");
  process.exit(1);
}

let exitCode = 1;
try {
  await ensureStubs();
  exitCode = await run(command);
} finally {
  if (!keep) await removeStubs();
}
process.exit(exitCode);

async function ensureStubs() {
  let wrote = false;
  for (const [rel, contents] of Object.entries(stubFiles)) {
    const abs = path.join(root, rel);
    let current = null;
    try {
      current = await readFile(abs, "utf8");
    } catch {
      current = null;
    }
    if (current !== null && !current.startsWith(marker)) continue;
    if (current === contents) continue;
    await mkdir(path.dirname(abs), { recursive: true });
    await writeFile(abs, contents);
    wrote = true;
  }
  if (wrote) console.log("mouses: using temporary pipeline and player stubs");
}

async function removeStubs() {
  for (const rel of Object.keys(stubFiles)) {
    const abs = path.join(root, rel);
    let text = "";
    try {
      text = await readFile(abs, "utf8");
    } catch {
      continue;
    }
    if (text.startsWith(marker)) await rm(abs, { force: true });
  }
  for (const dir of ["src/pipeline", "src/player"]) {
    const abs = path.join(root, dir);
    try {
      const names = await readdir(abs);
      if (names.length === 0) await rm(abs, { recursive: false });
    } catch {
      // Directory is already gone or still holds real modules.
    }
  }
}

function run(shellCommand) {
  return new Promise((resolve) => {
    const child = spawn(shellCommand, {
      cwd: root,
      stdio: "inherit",
      shell: true,
      env: process.env,
    });
    const stop = (signal) => {
      if (!child.killed) child.kill(signal);
    };
    process.once("SIGINT", () => stop("SIGINT"));
    process.once("SIGTERM", () => stop("SIGTERM"));
    child.on("exit", (code) => resolve(code ?? 1));
  });
}
